sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var statusField = 'u_trus_status'; 
   var category = 'u_type_of_request';

   if (category == 'Complaint') {
      g_form.addOption(statusField, 'awaiting_info', 'Awaiting Information');
      g_form.addOption(statusField, 'resolved_with_credit', 'Resolved with Credit');
   } 
   else if (category == 'Escalation') {
      g_form.addOption(statusField, 'information_provided', 'Information Provided');
      g_form.addOption(statusField, 'closed_complete', 'Closed Complete');
   } 
   else if (category == 'Inquiry') {
      g_form.addOption(statusField, 'pending_manager', 'Pending Manager Review');
      g_form.addOption(statusField, 'escalation_closed', 'Escalation Closed');
   }

}
